import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int force = fs.nextInt();

        char[][] map = new char[n][];
        for (int i = 0; i < n; i++) {
            map[i] = fs.next().toCharArray();
        }

        int[] queue = new int[n * n];
        int head = 0, tail = 0;

        if (map[0][0] - '0' <= force) {
            map[0][0] = '*';
            queue[tail++] = 0;
        }

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (head < tail) {
            int pos = queue[head++];
            int r = pos / n;
            int c = pos % n;

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];

                if (nr >= 0 && nr < n && nc >= 0 && nc < n
                        && map[nr][nc] != '*'
                        && map[nr][nc] - '0' <= force) {
                    map[nr][nc] = '*';
                    queue[tail++] = nr * n + nc;
                }
            }
        }

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            out.append(map[i]).append('\n');
        }
        System.out.print(out);
    }
}
